    pub stdin: bool,
    pub config: Option<PathBuf>,
    pub verbosity: LevelFilter,
    pub arguments: bool,
    pub files: Vec<String>,
    pub recursive: bool,
    pub lists: Vec<String>,
    pub verbatims: Vec<String>,
    pub no_indent_envs: Vec<String>,
    pub wrap_chars: Vec<char>,
}

const DEFAULT_LISTS: [&str; 5] =
    ["itemize", "enumerate", "description", "inlineroman", "inventory"];
const DEFAULT_VERBATIMS: [&str; 5] =
    ["verbatim", "Verbatim", "lstlisting", "minted", "comment"];
const DEFAULT_NO_INDENT_ENVS: [&str; 1] = ["document"];

/// Parse the command line arguments into optional arguments.
pub fn get_cli_args(matches: &ArgMatches) -> OptionArgs {
    let from_cli = |name: &str| {
        matches.value_source(name) == Some(ValueSource::CommandLine)
    };
    let flag = |name: &str| matches.get_flag(name).then_some(true);
    let verbosity = if matches.get_flag("trace") {
        Some(LevelFilter::Trace)
    } else if matches.get_flag("verbose") {
        Some(LevelFilter::Info)
    } else if matches.get_flag("quiet") {
        Some(LevelFilter::Error)
    } else {
        None
    };
    OptionArgs {
        check: flag("check"),
        print: flag("print"),
        fail_on_change: flag("fail-on-change"),
        wrap: matches.get_flag("nowrap").then_some(false),
        wraplen: from_cli("wraplen")
            .then(|| matches.get_one::<usize>("wraplen").copied())
            .flatten(),
        wrapmin: None,
        tabsize: from_cli("tabsize")
            .then(|| matches.get_one::<u8>("tabsize").copied())
            .flatten(),
        tabchar: matches.get_flag("usetabs").then_some(TabChar::Tab),
        stdin: flag("stdin"),
        config: matches.get_one::<PathBuf>("config").cloned(),
        noconfig: flag("noconfig"),
        verbosity,
        arguments: flag("args"),
        files: matches
            .get_many::<String>("files")
            .map(|v| v.cloned().collect())
            .unwrap_or_default(),
        recursive: flag("recursive"),
        lists: vec![],
        verbatims: vec![],
        no_indent_envs: vec![],
        wrap_chars: vec![],
    }
}

/// Combine the command line and configuration file arguments.
pub fn get_args() -> Args {
    let matches = command().get_matches();
    crate::cli::handle_special_modes(&matches);
    let cli = get_cli_args(&matches);
    let config = get_config(&cli);
    let config_args = config.map(|(path, text)| parse_config(&path, &text));
    resolve_args(cli, config_args)
}

fn resolve_args(cli: OptionArgs, config: Option<OptionArgs>) -> Args {
    let config_path = config.as_ref().and_then(|c| c.config.clone());
    let config = config.unwrap_or_default();
    let wraplen = cli.wraplen.or(config.wraplen).unwrap_or(80);
    let wrapmin = match cli.wrapmin.or(config.wrapmin) {
        Some(wrapmin) => wrapmin.min(wraplen),
        None if wraplen >= 50 => wraplen - 10,
        None => wraplen,
    };
    let mut lists: Vec<String> = config.lists.clone();
    lists.extend(DEFAULT_LISTS.iter().map(|s| s.to_string()));
    let mut verbatims: Vec<String> = config.verbatims.clone();
    verbatims.extend(DEFAULT_VERBATIMS.iter().map(|s| s.to_string()));
    let mut no_indent_envs: Vec<String> = config.no_indent_envs.clone();
    no_indent_envs
        .extend(DEFAULT_NO_INDENT_ENVS.iter().map(|s| s.to_string()));
    let mut wrap_chars: Vec<char> = config.wrap_chars.clone();
    wrap_chars.push(' ');
    Args {
        check: cli.check.or(config.check).unwrap_or(false),
        print: cli.print.or(config.print).unwrap_or(false),
        fail_on_change: cli
            .fail_on_change
            .or(config.fail_on_change)
            .unwrap_or(false),
        wrap: cli.wrap.or(config.wrap).unwrap_or(true),
        wraplen,
        wrapmin,
        tabsize: cli.tabsize.or(config.tabsize).unwrap_or(2),
        tabchar: cli.tabchar.or(config.tabchar).unwrap_or(TabChar::Space),
        stdin: cli.stdin.or(config.stdin).unwrap_or(false),
        config: config_path,
        verbosity: cli
            .verbosity
            .or(config.verbosity)
            .unwrap_or(LevelFilter::Warn),
        arguments: cli.arguments.unwrap_or(false),
        files: cli.files,
        recursive: cli.recursive.unwrap_or(false),
        lists,
        verbatims,
        no_indent_envs,
        wrap_chars,
    }
}

impl Args {
    /// Check the resolved arguments for problems, recording errors.
    /// Returns the exit code.
    pub fn resolve(&mut self, logs: &mut Vec<Log>) -> u8 {
        let mut exit_code = 0;
        if self.recursive {
            self.files = crate::read::find_files(&self.files);
        } else {
            let dirs = self.files.iter().any(|f| std::path::Path::new(f).is_dir());
            if dirs {
                record_log(
                    logs,
                    Error,
                    "",
                    "A directory was passed without --recursive.",
                );
                exit_code = 1;
            }
        }
        if self.stdin && !self.files.is_empty() {
            record_log(
                logs,
                Error,
                "",
                "Do not provide file name(s) when using --stdin.",
            );
            exit_code = 1;
        }
        if !self.stdin && self.files.is_empty() {
            record_log(
                logs,
                Error,
                "",
                "No files specified. Provide filenames, or pass --recursive or --stdin.",
            );
            exit_code = 1;
        }
        exit_code
    }

    /// Print the resolved arguments to stdout.
    pub fn print(&self) {
        let pad = " ".repeat(27);
        let field = |name: &str| format!("{}:", name.bold());
        let list = |items: &[String]| items.join(&format!("\n{pad}"));
        let config = match &self.config {
            Some(path) => path.display().to_string(),
            None => "None".to_string(),
        };
        let verbosity = match self.verbosity {
            LevelFilter::Off => "off",
            LevelFilter::Error => "error",
            LevelFilter::Warn => "warn",
            LevelFilter::Info => "info",
            LevelFilter::Debug => "debug",
            LevelFilter::Trace => "trace",
        };
        let wrap_chars: Vec<String> =
            self.wrap_chars.iter().map(|c| c.to_string()).collect();
        println!("{}", "tex-fmt".magenta().bold());
        println!("  {:<25}{}", field("check"), self.check);
        println!("  {:<25}{}", field("print"), self.print);
        println!("  {:<25}{}", field("fail-on-change"), self.fail_on_change);
        println!("  {:<25}{}", field("wrap"), self.wrap);
        println!("  {:<25}{}", field("wraplen"), self.wraplen);
        println!("  {:<25}{}", field("wrapmin"), self.wrapmin);
        println!("  {:<25}{}", field("tabsize"), self.tabsize);
        println!("  {:<25}{}", field("tabchar"), self.tabchar.name());
        println!("  {:<25}{}", field("stdin"), self.stdin);
        println!("  {:<25}{}", field("config"), config);
        println!("  {:<25}{}", field("verbosity"), verbosity);
        println!("  {:<25}{}", field("lists"), list(&self.lists));
        println!("  {:<25}{}", field("verbatims"), list(&self.verbatims));
        println!("  {:<25}{}", field("no-indent-envs"), list(&self.no_indent_envs));
        println!("  {:<25}{}", field("wrap-chars"), list(&wrap_chars));
    }
}
