}

/// Find the root of the current git repository by walking upwards
/// until a directory containing `.git` is found.
fn find_git_root() -> Option<PathBuf> {
    let mut dir = current_dir().ok()?;
    loop {
        if dir.join(".git").is_dir() {
            return Some(dir);
        }
        if !dir.pop() {
            return None;
        }
    }
}

/// Look for a configuration file in the root of the git repository.
fn find_config_in_git_root() -> Option<PathBuf> {
    let path = find_git_root()?.join(CONFIG);
    path.exists().then_some(path)
}

/// Look for a configuration file in the user's configuration directory.
fn find_config_in_user_dir() -> Option<PathBuf> {
    let path = dirs::config_dir()?.join("tex-fmt").join(CONFIG);
    path.exists().then_some(path)
}

/// Resolve the location of the configuration file.
fn find_config(cli: &OptionArgs) -> Option<PathBuf> {
    if cli.noconfig == Some(true) {
        return None;
    }
    if let Some(path) = &cli.config {
        return Some(path.clone());
    }
    find_config_in_cwd()
        .or_else(find_config_in_git_root)
        .or_else(find_config_in_user_dir)
}

/// Convert a verbosity name into a level filter.
fn get_verbosity(name: &str) -> LevelFilter {
    match name {
        "error" | "quiet" => LevelFilter::Error,
        "warn" => LevelFilter::Warn,
        "info" | "verbose" => LevelFilter::Info,
        "trace" => LevelFilter::Trace,
        _ => LevelFilter::Warn,
    }
}

/// Convert a tab character name into a tab character.
fn get_tabchar(name: &str) -> TabChar {
    match name {
        "tab" => TabChar::Tab,
        _ => TabChar::Space,
    }
}

/// Read the configuration file, returning its path and contents.
pub fn get_config(cli: &OptionArgs) -> Option<(PathBuf, String)> {
    let config_path = find_config(cli)?;
    let config_text = fs::read_to_string(config_path.as_path()).unwrap();
    Some((config_path, config_text))
}

/// Extract a list of strings from a configuration table entry.
fn get_string_list(table: &Table, key: &str) -> Vec<String> {
    match table.get(key).and_then(|v| v.as_array()) {
        Some(array) => array
            .iter()
            .filter_map(|v| v.as_str().map(ToString::to_string))
            .collect(),
        None => vec![],
    }
}

/// Convert a string containing a single character into that character.
fn char_from_string(s: &str) -> char {
    let mut chars = s.chars();
    let c = chars.next().expect("String is empty");
    assert!(chars.next().is_none(), "String contains more than one character");
    c
}

