    let config = config;
    let noconfig = noconfig;
    let arguments = arguments;
    let files = files;
    let recursive = recursive;
    let check = table.get("check").map(|v| v.as_bool().unwrap());
    let print = table.get("print").map(|v| v.as_bool().unwrap());
    let fail_on_change = table
        .get("fail-on-change")
        .map(|val| val.as_bool().unwrap());
    let wrap = table.get("wrap").map(|v| v.as_bool().unwrap());
    let wraplen = table
        .get("wraplen")
        .map(|val| val.as_integer().unwrap().try_into().unwrap());
    let wrapmin = table
        .get("wrapmin")
        .map(|val| val.as_integer().unwrap().try_into().unwrap());
    let tabsize = table
        .get("tabsize")
        .map(|val| val.as_integer().unwrap().try_into().unwrap());
    let stdin = table.get("stdin").map(|v| v.as_bool().unwrap());
    OptionArgs {
        check,
        print,
        fail_on_change,
        wrap,
        wraplen,
        wrapmin,
        tabsize,
        tabchar,
        stdin,
        config,
        noconfig,
        verbosity,
        arguments,
        files,
        recursive,
        lists,
        verbatims,
        no_indent_envs,
        wrap_chars,
    }
}
