//! Collection, deduplication and printing of log messages.

use colored::Colorize;
use log::Level;
use log::LevelFilter;
use std::io::Write;

/// A single log entry.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Log {
    /// Severity of the message.
    pub level: Level,
    /// File which the message refers to.
    pub file: String,
    /// Line number in the formatted output, if applicable.
    pub linum_new: Option<usize>,
    /// Line number in the original source, if applicable.
    pub linum_old: Option<usize>,
    /// Text of the line which the message refers to, if applicable.
    pub line: Option<String>,
    /// The message itself.
    pub message: String,
}

/// Set up the terminal logger with the requested verbosity.
pub fn init_logger(filter: LevelFilter) {
    env_logger::Builder::new()
        .filter_level(filter)
        .format(|buf, record| writeln!(buf, "{}", record.args()))
        .init();
}

/// Record a log message which refers to a particular line of a file.
#[allow(clippy::too_many_arguments)]
pub fn record_file_log(
    logs: &mut Vec<Log>,
    level: Level,
    file: &str,
    linum_new: usize,
    linum_old: usize,
    line: &str,
    message: &str,
) {
    logs.push(Log {
        level,
        file: file.to_string(),
        linum_new: Some(linum_new),
        linum_old: Some(linum_old),
        line: Some(line.to_string()),
        message: message.to_string(),
    });
}

/// Record a log message which refers to a file as a whole.
pub fn record_log(logs: &mut Vec<Log>, level: Level, file: &str, message: &str) {
    logs.push(Log {
        level,
        file: file.to_string(),
        linum_new: None,
        linum_old: None,
        line: None,
        message: message.to_string(),
    });
}

/// Format a log entry for the terminal.
fn format_log(log: &Log) -> String {
    let level = match log.level {
        Level::Error => "ERROR".red().bold(),
        Level::Warn => "WARN".yellow().bold(),
        Level::Info => "INFO".cyan().bold(),
        Level::Debug => "DEBUG".blue().bold(),
        Level::Trace => "TRACE".green().bold(),
    };
    let linum_new = log
        .linum_new
        .map_or_else(String::new, |n| format!("Line {n} "));
    let linum_old = log
        .linum_old
        .map_or_else(String::new, |n| format!("({n}). "));
    let line = log.line.clone().unwrap_or_default();
    format!(
        "{}: {} {}: {}{}{} {}",
        level,
        "tex-fmt".magenta().bold(),
        log.file.blue().bold(),
        linum_new.white().bold(),
        linum_old.white().bold(),
        log.message.yellow().bold(),
        line,
    )
}

/// Remove duplicated log entries.
///
/// Entries are grouped by level, line numbers and message, and within
/// each group only the final copy of any repeated entry is retained.
/// The original ordering of the surviving entries is preserved.
fn deduplicate(logs: Vec<Log>) -> Vec<Log> {
    let mut indexed: Vec<(usize, Log)> = logs.into_iter().enumerate().collect();
    indexed.sort_by(|(_, a), (_, b)| {
        (a.level, a.linum_new, a.linum_old, &a.message).cmp(&(
            b.level,
            b.linum_new,
            b.linum_old,
            &b.message,
        ))
    });
    let mut keep = vec![true; indexed.len()];
    for i in 1..indexed.len() {
        if indexed[i].1 == indexed[i - 1].1 {
            keep[indexed[i - 1].0] = false;
        }
    }
    indexed.sort_by_key(|(i, _)| *i);
    indexed
        .into_iter()
        .filter(|(i, _)| keep[*i])
        .map(|(_, log)| log)
        .collect()
}

/// Print all recorded logs to the terminal.
pub fn print_logs(logs: Vec<Log>) {
    for log in deduplicate(logs) {
        log::log!(log.level, "{}", format_log(&log));
    }
}
