//! Reading of source files and discovery of files to format.

use crate::logging::{record_log, Log};
use log::Level::Error;
use std::fs;
use std::path::Path;

/// File extensions which are recognised as LaTeX sources.
const EXTENSIONS: [&str; 4] = ["tex", "bib", "cls", "sty"];

/// Read a file, returning its resolved name and its contents.
pub fn read(file: &str, logs: &mut Vec<Log>) -> Option<(String, String)> {
    let mut file = file.to_string();
    if Path::new(&file).extension().is_none() {
        file.push_str(".tex");
    }
    let ext = Path::new(&file).extension().unwrap().to_string_lossy();
    match fs::read_to_string(&file) {
        Ok(text) => Some((file, text)),
        Err(_) => {
            if EXTENSIONS.contains(&ext.as_ref()) {
                record_log(logs, Error, &file, "Could not open file.");
            } else {
                record_log(logs, Error, &file, "File type invalid.");
            }
            None
        }
    }
}

/// Read the whole of stdin as a string.
pub fn read_stdin(logs: &mut Vec<Log>) -> Option<String> {
    let mut text = String::new();
    match std::io::stdin().read_line_all(&mut text) {
        Ok(()) => Some(text),
        Err(e) => {
            let message = format!("Could not read from stdin: {e}");
            record_log(logs, Error, "<stdin>", &message);
            None
        }
    }
}

/// Helper trait for reading all of stdin.
trait ReadAll {
    fn read_line_all(&mut self, buf: &mut String) -> std::io::Result<()>;
}

impl ReadAll for std::io::Stdin {
    fn read_line_all(&mut self, buf: &mut String) -> std::io::Result<()> {
        use std::io::Read;
        self.read_to_string(buf).map(|_| ())
    }
}

/// Does this path have a recognised LaTeX file extension?
fn has_valid_extension(path: &Path) -> bool {
    path.extension()
        .and_then(|e| e.to_str())
        .is_some_and(|e| EXTENSIONS.contains(&e))
}

/// Recursively search the given paths for files to format.
///
/// Files are searched for using the conventions of `.gitignore` and
/// `.ignore` files, and hidden files are skipped. Paths which are
/// passed directly and refer to files are always included.
pub fn find_files(paths: &[String]) -> Vec<String> {
    let roots: Vec<String> = if paths.is_empty() {
        vec![".".to_string()]
    } else {
        paths.to_vec()
    };
    let mut files = Vec::new();
    for root in roots {
        if Path::new(&root).is_file() {
            files.push(root);
            continue;
        }
        for entry in ignore::WalkBuilder::new(&root).build().flatten() {
            let path = entry.path();
            let is_file = entry.file_type().is_some_and(|t| t.is_file());
            if is_file && has_valid_extension(path) {
                files.push(path.to_string_lossy().to_string());
            }
        }
    }
    files
}
