//! Handling of the `% tex-fmt: skip`, `% tex-fmt: off` and
//! `% tex-fmt: on` directives.

use crate::format::State;
use crate::logging::{record_file_log, Log};
use log::Level::Warn;

/// Marker for skipping a single line.
const SKIP: &str = "% tex-fmt: skip";
/// Marker for the start of an ignored block.
const OFF: &str = "% tex-fmt: off";
/// Marker for the end of an ignored block.
const ON: &str = "% tex-fmt: on";

/// Ignore state for the current line.
#[derive(Clone, Copy, Debug, Default)]
pub struct Ignore {
    /// Whether we are currently inside an ignored block.
    pub actual: bool,
    /// Whether the current line should be left untouched.
    pub visual: bool,
}

/// Determine the ignore state for the current line.
pub fn get_ignore(
    line: &str,
    state: &State,
    file: &str,
    logs: &mut Vec<Log>,
) -> Ignore {
    let prev = state.ignore;
    let text = line.trim_start();
    if text.ends_with(SKIP) {
        return Ignore {
            actual: prev.actual,
            visual: true,
        };
    }
    if text.ends_with(OFF) {
        if prev.actual {
            record_file_log(
                logs,
                Warn,
                file,
                state.linum_new,
                state.linum_old,
                text,
                "Cannot begin ignore block:",
            );
        }
        return Ignore {
            actual: true,
            visual: true,
        };
    }
    if text.ends_with(ON) {
        if !prev.actual {
            record_file_log(
                logs,
                Warn,
                file,
                state.linum_new,
                state.linum_old,
                text,
                "No ignore block to end.",
            );
        }
        return Ignore {
            actual: false,
            visual: true,
        };
    }
    Ignore {
        actual: prev.actual,
        visual: prev.actual,
    }
}
