use crate::args::Args;
use crate::format::State;
use crate::logging::{record_file_log, Log};
use log::Level::Warn;

/// Verbatim state for the current line.
#[derive(Clone, Copy, Debug, Default)]
pub struct Verbatim {
    /// Nesting depth of verbatim environments.
    pub actual: i8,
    /// Whether the current line is part of a verbatim environment.
    pub visual: bool,
}

/// Determine the verbatim state for the current line.
pub fn get_verbatim(
    line: &str,
    state: &State,
    file: &str,
    args: &Args,
    logs: &mut Vec<Log>,
) -> Verbatim {
    let prev = state.verbatim;
    let mut actual = prev.actual;
    let begins = args
        .verbatims
        .iter()
        .any(|v| line.contains(&format!("\\begin{{{v}}}")));
    let ends = args
        .verbatims
        .iter()
        .any(|v| line.contains(&format!("\\end{{{v}}}")));
    if begins {
        actual += 1;
    } else if ends {
        actual -= 1;
