//! Calculation and application of indentation.

use crate::args::{Args, TabChar};
use crate::comments::remove_comment;

/// Pattern marking the start of an environment.
pub const ENV_BEGIN: &str = "\\begin{";
/// Pattern marking the end of an environment.
pub const ENV_END: &str = "\\end{";
/// Pattern marking an item in a list.
pub const ITEM: &str = "\\item";

/// Indentation state.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct Indent {
    /// Indentation level after the current line.
    pub actual: i8,
    /// Indentation level applied to the current line.
    pub visual: i8,
}

/// Does the line contain `\item` as a command (not as a prefix of a
/// longer command name) starting at the given byte index?
pub fn is_item_at(line: &str, index: usize) -> bool {
    let rest = &line[index..];
    if !rest.starts_with(ITEM) {
        return false;
    }
    match rest[ITEM.len()..].chars().next() {
        Some(c) => !c.is_ascii_alphabetic(),
        None => true,
    }
}

/// Does the line contain an `\item` command anywhere?
fn contains_item(line: &str) -> bool {
    line.char_indices().any(|(i, _)| is_item_at(line, i))
}

/// Does the line contain the beginning or end of an environment from
/// the given list?
fn contains_env(line: &str, pattern: &str, envs: &[String]) -> bool {
    envs.iter().any(|e| line.contains(&format!("{pattern}{e}}}")))
}

/// Change in indentation due to a single character.
fn get_diff_char(c: char) -> i8 {
    match c {
        '{' | '[' | '(' => 1,
        '}' | ']' | ')' => -1,
        _ => 0,
    }
}

/// Total change in indentation caused by the current line.
fn get_diff(line: &str, args: &Args) -> i8 {
    let mut diff: i8 = 0;
    if line.contains(ENV_BEGIN) && !contains_env(line, ENV_BEGIN, &args.no_indent_envs) {
        diff += 1;
        diff += i8::from(contains_env(line, ENV_BEGIN, &args.lists));
    }
    if line.contains(ENV_END) && !contains_env(line, ENV_END, &args.no_indent_envs) {
        diff -= 1;
        diff -= i8::from(contains_env(line, ENV_END, &args.lists));
    }
    diff + line.chars().map(get_diff_char).sum::<i8>()
}

/// Amount by which the current line is pulled back relative to the
/// indentation level before it.
fn get_back(line: &str, prev: &Indent, args: &Args) -> i8 {
    let mut back: i8 = 0;
    let mut cumul: i8 = 0;
    for c in line.chars() {
        cumul -= get_diff_char(c);
        back = back.max(cumul);
    }
    if prev.actual != 0 {
        if line.contains(ENV_END) && !contains_env(line, ENV_END, &args.no_indent_envs) {
            back += 1;
            back += i8::from(contains_env(line, ENV_END, &args.lists));
        }
        if contains_item(line) {
            back += 1;
        }
    }
    back
}

/// Calculate the indentation state for the current line.
pub fn calculate_indent(line: &str, prev: &Indent, args: &Args) -> Indent {
    let text = remove_comment(line);
    let diff = get_diff(text, args);
    let back = get_back(text, prev, args);
    Indent {
        actual: prev.actual + diff,
        visual: prev.actual - back,
    }
}

/// Apply the indentation to a line, trimming any existing whitespace.
pub fn apply_indent(line: &str, indent: &Indent, args: &Args) -> String {
    let text = line.trim();
    if text.is_empty() || indent.visual <= 0 {
        return text.to_string();
    }
    let n = indent.visual as usize * args.tabsize as usize;
    let tab = match args.tabchar {
        TabChar::Space => " ",
        TabChar::Tab => "\t",
    };
    format!("{}{}", tab.repeat(n), text)
}
EOF
