        prev_prev = prev;
        prev = Some(c);
    }
    wrap_point
}

/// Split a long line into two parts, returning them without their
/// indentation. Returns `None` if the line cannot be split.
pub fn apply_wrap(
    line: &str,
    indent_len: usize,
    state: &State,
    file: &str,
    args: &Args,
    logs: &mut Vec<Log>,
) -> Option<(String, String)> {
    let text = line.trim_start();
    let warn = |logs: &mut Vec<Log>| {
        record_file_log(
            logs,
            Warn,
            file,
            state.linum_new,
            state.linum_old,
            text,
            "Line cannot be wrapped.",
        );
    };
    let Some(wrap_point) = find_wrap_point(line, indent_len, args) else {
        warn(logs);
        return None;
    };
    let (byte_index, wrap_char) = line.char_indices().nth(wrap_point)?;
    if byte_index >= args.wraplen {
        warn(logs);
    }
    let split = byte_index + wrap_char.len_utf8();
    let first = line[..split].trim_start().to_string();
    let rest = line[split..].trim_start();
    if rest.is_empty() {
        return None;
    }
    let in_comment = find_comment_index(line).is_some_and(|c| byte_index > c);
    let rest = if in_comment {
        format!("% {rest}")
    } else {
        rest.to_string()
    };
    Some((first, rest))
}
