/// Find the byte index at which an environment or item command should
/// be moved onto a new line, if any.
fn find_env_split(line: &str) -> Option<usize> {
    let comment = find_comment_index(line).unwrap_or(line.len());
    let start = line.len() - line.trim_start().len();
    for (i, _) in line.char_indices() {
        if i >= comment {
            break;
        }
        if i <= start {
            continue;
        }
        let rest = &line[i..];
        if rest.starts_with(ENV_BEGIN)
            || rest.starts_with(ENV_END)
            || is_item_at(line, i)
        {
            return Some(i);
        }
    }
    None
}

/// Format the text of a single file.
pub fn format_file(
    old_text: &str,
    file: &str,
    args: &Args,
    logs: &mut Vec<Log>,
) -> String {
    record_log(logs, Info, file, "Formatting started.");
    let mut state = State::default();
    let text = remove_extra_newlines(old_text);
    let mut queue = get_lines(&text);
    queue.reverse();
    let mut new_lines: Vec<String> = Vec::new();
    let mut last_zero_indent: usize = 1;
    let mut first_negative_indent: Option<usize> = None;

    while let Some((linum_old, line)) = queue.pop() {
        state.linum_old = linum_old;
        state.linum_new = new_lines.len() + 1;
        state.ignore = get_ignore(&line, &state, file, logs);
        state.verbatim = get_verbatim(&line, &state, file, args, logs);
        if state.ignore.visual || state.verbatim.visual {
            new_lines.push(line);
            continue;
        }
        let text = line.trim_start();

        // Place environments and items on their own lines
        if let Some(index) = find_env_split(&line) {
            record_file_log(
                logs,
                Trace,
                file,
                state.linum_new,
                state.linum_old,
                text,
                "Placing environment on new line.",
            );
            let first = line[..index].to_string();
            let rest = line[index..].to_string();
            queue.push((linum_old, rest));
            queue.push((linum_old, first));
            continue;
        }

        // Calculate and apply indentation
        let indent = calculate_indent(&line, &state.indent, args);
        let message = format!(
            "Indent: actual = {}, visual = {}:",
            indent.actual, indent.visual
        );
        record_file_log(
            logs,
            Trace,
            file,
            state.linum_new,
            state.linum_old,
            text,
            &message,
        );
        let negative = indent.actual < 0 || indent.visual < 0;
        if negative {
            record_file_log(
                logs,
                Warn,
                file,
                state.linum_new,
                state.linum_old,
                text,
                "Indent is negative.",
            );
        }
        let indented = apply_indent(&line, &indent, args);

        // Wrap long lines
        if args.wrap && needs_wrap(&indented, args) {
            record_file_log(
                logs,
                Trace,
                file,
                state.linum_new,
                state.linum_old,
                text,
                "Wrapping long line.",
            );
            let indent_len = indented.len() - indented.trim_start().len();
            let wrapped =
                apply_wrap(&indented, indent_len, &state, file, args, logs);
            if let Some((first, rest)) = wrapped {
                queue.push((linum_old, rest));
                queue.push((linum_old, first));
                continue;
            }
        }

        // Commit the line
        state.indent = indent;
        if indent.visual == 0 {
            last_zero_indent = state.linum_new;
        }
        if negative && first_negative_indent.is_none() {
            first_negative_indent = Some(state.linum_new);
        }
        new_lines.push(indented);
    }

    if state.indent.actual != 0 {
        let message = format!(
            "Indent does not return to zero. Last non-indented line is line {last_zero_indent}"
        );
        record_log(logs, Warn, file, &message);
    }
    if let Some(linum) = first_negative_indent {
        let message = format!(
            "Negative indents. First negatively indented line is line {linum}"
        );
        record_log(logs, Warn, file, &message);
    }
    record_log(logs, Info, file, "Formatting complete.");

    let mut new_text = new_lines.join("\n");
    new_text.truncate(new_text.trim_end().len());
    new_text.push('\n');
    new_text
}
