//! tex-fmt: an extremely fast LaTeX formatter.

mod args;
mod cli;
mod comments;
mod config;
mod format;
mod ignore;
mod indent;
mod logging;
mod read;
mod subs;
mod verbatim;
mod wrap;
mod write;

