use crate::format::format_file;
use crate::logging::{init_logger, print_logs, record_log, Log};
use crate::read::{read, read_stdin};
use crate::write::{print_text, write_file};
use log::Level::Error;
use std::process::ExitCode;

/// Format a single file, returning whether the run should fail.
fn run_file(file: &str, args: &Args, logs: &mut Vec<Log>) -> bool {
    let Some((file, old_text)) = read(file, logs) else {
        return true;
    };
    let new_text = format_file(&old_text, &file, args, logs);
    if args.print {
        print_text(&new_text);
        return false;
    }
    let changed = new_text != old_text;
    if args.check {
        if changed {
            record_log(logs, Error, &file, "Incorrect formatting.");
        }
        return changed;
    }
    if changed {
        write_file(&file, &new_text);
    }
    changed && args.fail_on_change
}

/// Format the contents of stdin, returning whether the run should fail.
fn run_stdin(args: &Args, logs: &mut Vec<Log>) -> bool {
    let Some(old_text) = read_stdin(logs) else {
        return true;
    };
    let new_text = format_file(&old_text, "<stdin>", args, logs);
    print_text(&new_text);
    false
}

fn main() -> ExitCode {
    let mut args = get_args();
    init_logger(args.verbosity);
    if args.arguments {
        args.print();
        return ExitCode::SUCCESS;
    }
    let mut logs: Vec<Log> = Vec::new();
    let mut exit_code = args.resolve(&mut logs);
    if exit_code == 0 {
        let failed = if args.stdin {
            run_stdin(&args, &mut logs)
        } else {
            let mut failed = false;
            for file in &args.files {
                failed |= run_file(file, &args, &mut logs);
            }
            failed
        };
        if failed {
            exit_code = 1;
        }
    }
    print_logs(logs);
    ExitCode::from(exit_code)
}
