//! Generation of the manual page from the command line definition.

use clap::{Arg, Command};
use roff::{bold, italic, roman, Inline, Roff};
use std::io;

/// Render the manual page for the command to the given writer.
pub fn render(cmd: &Command, out: &mut dyn io::Write) -> io::Result<()> {
    let name = cmd.get_name().to_string();
    let version = cmd.get_version().unwrap_or_default();
    let about = cmd
        .get_about()
        .map(ToString::to_string)
        .unwrap_or_default();
    let mut roff = Roff::default();
    roff.control("TH", [name.as_str(), "1", "", &format!("{name} {version}"), ""]);
    roff.control("SH", ["NAME"]);
    roff.text([roman(format!("{name} - {about}"))]);
    roff.control("SH", ["SYNOPSIS"]);
    roff.text(synopsis(cmd));
    roff.control("SH", ["DESCRIPTION"]);
    roff.text([roman(about)]);
    roff.control("SH", ["OPTIONS"]);
    options(&mut roff, cmd);
    roff.control("SH", ["VERSION"]);
    roff.text([roman(format!("v{version}"))]);
    if let Some(author) = cmd.get_author() {
        roff.control("SH", ["AUTHORS"]);
        roff.text([roman(author)]);
    }
    roff.to_writer(out)
}

/// Opening and closing markers for an argument, depending on whether
/// it is required.
fn markers(arg: &Arg) -> (&'static str, &'static str) {
    if arg.is_required_set() {
        ("<", ">")
    } else {
        ("[", "]")
    }
}

/// Build the synopsis line listing every argument.
fn synopsis(cmd: &Command) -> Vec<Inline> {
    let mut line = vec![bold(cmd.get_name()), roman(" ")];
    for arg in cmd.get_arguments() {
        let (lhs, rhs) = markers(arg);
        match (arg.get_short(), arg.get_long()) {
            (Some(short), Some(long)) => {
                line.push(roman(lhs));
                line.push(bold(format!("-{short}")));
                line.push(roman("|"));
                line.push(bold(format!("--{long}")));
                line.push(roman(rhs));
            }
            (Some(short), None) => {
                line.push(roman(lhs));
                line.push(bold(format!("-{short}")));
                line.push(roman(rhs));
            }
            (None, Some(long)) => {
                line.push(roman(lhs));
                line.push(bold(format!("--{long}")));
                line.push(roman(rhs));
            }
            (None, None) => {
                line.push(roman(lhs));
                line.push(italic(arg.get_id().as_str()));
                line.push(roman(rhs));
            }
        }
        line.push(roman(" "));
    }
    line
}

/// Describe every option and positional argument.
fn options(roff: &mut Roff, cmd: &Command) {
    let args: Vec<&Arg> = cmd.get_arguments().collect();
    for arg in args.iter().filter(|a| !a.is_positional()) {
        let mut header = vec![];
        match (arg.get_short(), arg.get_long()) {
            (Some(short), Some(long)) => {
                header.push(bold(format!("-{short}")));
                header.push(roman(", "));
                header.push(bold(format!("--{long}")));
            }
            (Some(short), None) => header.push(bold(format!("-{short}"))),
            (None, Some(long)) => header.push(bold(format!("--{long}"))),
            (None, None) => {}
        }
        if let Some(names) = arg.get_value_names() {
            for name in names {
                header.push(roman(" "));
                header.push(italic(format!("<{name}>")));
            }
        }
        roff.control("TP", []);
        roff.text(header);
        let help_written = write_help(roff, arg);
        possible_values(roff, arg, help_written);
    }
    for arg in args.iter().filter(|a| a.is_positional()) {
        let (lhs, rhs) = markers(arg);
        let value = match arg.get_value_names() {
            Some(names) => names.join(" "),
            None => arg.get_id().to_string(),
        };
        roff.control("TP", []);
        roff.text([roman(lhs), italic(value), roman(rhs)]);
        let help_written = write_help(roff, arg);
        possible_values(roff, arg, help_written);
    }
}

/// Write the help text of an argument, returning whether any was found.
fn write_help(roff: &mut Roff, arg: &Arg) -> bool {
    match arg.get_long_help().or_else(|| arg.get_help()) {
        Some(help) => {
            roff.text([roman(help.to_string())]);
            true
        }
        None => false,
    }
}

/// List the possible values of an argument, if any.
fn possible_values(roff: &mut Roff, arg: &Arg, help_written: bool) {
    if arg.is_hide_possible_values_set() {
        return;
    }
    let values: Vec<String> = arg
        .get_possible_values()
        .iter()
        .filter(|v| !v.is_hide_set())
        .map(|v| v.get_name().to_string())
        .collect();
    if values.is_empty() {
        return;
    }
    if help_written {
        roff.text([Inline::LineBreak]);
    }
    roff.text([
        Inline::LineBreak,
        roman("["),
        italic("possible values: "),
        roman(values.join(", ")),
        roman("]"),
    ]);
}
