//! Command line interface definition and handling of special modes.

use crate::man::render;
use clap::{value_parser, Arg, ArgAction, ArgMatches, Command};
use clap_complete::Shell;
use std::io;
use std::path::PathBuf;

/// Layout of the help message, showing the name and version first.
const HELP_TEMPLATE: &str =
    "{name} {version}\n\n{about-with-newline}\n{usage-heading} {usage}\n\n{all-args}{after-help}";

/// Build the command line interface.
pub fn command() -> Command {
    Command::new("tex-fmt")
        .version("0.5.6")
        .author("William George Underwood, wg.underwood13@gmail.com")
        .about("LaTeX formatter written in Rust")
        .help_template(HELP_TEMPLATE)
        .arg(flag("check", 'c', "Check formatting, do not modify files"))
        .arg(flag("print", 'p', "Print to stdout, do not modify files"))
        .arg(flag("fail-on-change", 'f', "Format files and return non-zero exit code if files are modified"))
        .arg(flag("nowrap", 'n', "Do not wrap long lines"))
        .arg(value("wraplen", 'l', "N", "Line length for wrapping [default: 80]").value_parser(value_parser!(usize)))
        .arg(value("tabsize", 't', "N", "Number of characters to use as tab size [default: 2]").value_parser(value_parser!(u8)))
        .arg(long_flag("usetabs", "Use tabs instead of spaces for indentation"))
        .arg(flag("stdin", 's', "Process stdin as a single file, output to stdout"))
        .arg(Arg::new("config").long("config").value_name("PATH").value_parser(value_parser!(PathBuf)).help("Path to config file"))
        .arg(long_flag("noconfig", "Do not read any config file"))
        .arg(flag("verbose", 'v', "Show info messages"))
        .arg(flag("quiet", 'q', "Hide warning messages"))
        .arg(long_flag("trace", "Show trace messages"))
        .arg(Arg::new("completion").long("completion").value_name("SHELL").value_parser(value_parser!(Shell)).help("Generate shell completion script"))
        .arg(long_flag("man", "Generate man page"))
        .arg(long_flag("args", "Print arguments passed to tex-fmt and exit"))
        .arg(flag("recursive", 'r', "Recursively search for files to format"))
        .arg(Arg::new("files").value_name("files").action(ArgAction::Append).help("List of files to be formatted"))
}

/// Handle the modes which print something and exit without formatting.
pub fn handle_special_modes(matches: &ArgMatches) {
    if let Some(shell) = matches.get_one::<Shell>("completion") {
        let mut cmd = command();
        clap_complete::generate(*shell, &mut cmd, "tex-fmt", &mut io::stdout());
        std::process::exit(0);
    }
    if matches.get_flag("man") {
        let cmd = command();
        render(&cmd, &mut io::stdout()).unwrap();
        std::process::exit(0);
    }
}

/// A boolean flag with both a short and a long form.
fn flag(name: &'static str, short: char, help: &'static str) -> Arg {
    Arg::new(name).short(short).long(name).action(ArgAction::SetTrue).help(help)
}

/// A boolean flag with only a long form.
fn long_flag(name: &'static str, help: &'static str) -> Arg {
    Arg::new(name).long(name).action(ArgAction::SetTrue).help(help)
}

/// An option taking a single value.
fn value(name: &'static str, short: char, value_name: &'static str, help: &'static str) -> Arg {
    Arg::new(name).short(short).long(name).value_name(value_name).help(help)
}
