/// where positions are measured including the indentation. A
/// character is only suitable once some text other than whitespace
/// and comment characters has been seen, and it must not be preceded
/// by a backslash or be the final character of the line.
fn find_wrap_point(text: &str, indent_len: usize, args: &Args) -> Option<usize> {
    let mut wrap_point = None;
    let mut prev: Option<char> = None;
    let mut seen_text = false;
    let last = text.chars().count().saturating_sub(1);
    for (i, c) in text.chars().enumerate() {
        let width = indent_len + i;
        if width >= args.wrapmin && wrap_point.is_some() || i >= last {
            break;
        }
        let escaped = prev == Some('\\\\');
        if seen_text && args.wrap_chars.contains(&c) && !escaped {
            wrap_point = Some(i);
        }
        if !c.is_whitespace() && c != '%' {
            seen_text = true;
        }
        prev = Some(c);
    }
    wrap_point
